"use strict";
(()=>{const path=`/adventures/${adventure17.slug}/`;let s={scene:0,selected:null,history:[]};const esc=v=>{const x=document.createElement("span");x.textContent=v;return x.innerHTML};const active=()=>location.pathname.startsWith(path);function controls(){return `<div class="controls-wrap"><span class="controls-label">Adventure Controls</span><div class="controls"><button class="control" data-tw-action="share">Share</button><button class="control" data-tw-action="restart">Restart</button><button class="control" data-tw-action="back" ${s.selected!==null||s.history.length?"":"disabled"}>Back Up</button><button class="control" data-tw-action="end">End</button></div></div>`}function render(pos="scene"){const scene=adventure17.scenes[s.scene],sel=s.selected;const choices=scene.choices.map((c,i)=>sel!==null&&sel!==i?"":`<button class="choice ${sel===i?"selected":""}" data-tw-choice="${i}" ${sel!==null?"disabled":""}>${esc(c[1])}</button>`).join("");let result="";if(sel!==null){const c=scene.choices[sel];result=`<div class="consequence" aria-live="polite"><p>${esc(c[2])}</p>`;result+=scene.final?`<p class="ending-name">Ending: ${esc(c[3])}</p><p>${esc(c[4])}</p></div>`:`</div><button class="continue" data-tw-action="continue">Continue</button>`}const continued=s.scene>0?`<span class="adventure-context-continued">continued</span>`:"";document.querySelector("#app").innerHTML=`<article class="card ${scene.final&&sel!==null?"ending":""}"><div class="adventure-context"><p class="adventure-context-title">${esc(adventure17.title)}</p>${continued}</div><h2>${scene.title}</h2><div class="story">${scene.body}</div><p class="question">${scene.question}</p><div class="choices">${choices}</div>${result}${controls()}</article>`;(pos==="result"?document.querySelector(".consequence"):pos==="decision"?document.querySelector(".question"):document.querySelector("#app"))?.scrollIntoView({block:"start"})}function tile(){if(active()||document.querySelector("[data-tw-start]"))return;const list=document.querySelector(".compact-adventure-list");if(!list)return;const a=document.createElement("a");a.className="compact-adventure";a.href=`${path}?fresh=1`;a.dataset.twStart="1";a.innerHTML=`<strong>${esc(adventure17.title)}</strong>`;list.append(a);const summary=document.querySelector(".browse-adventures summary");if(summary)summary.textContent=summary.textContent.replace(/Browse all \d+ adventures/,"Browse all 16 adventures")}document.addEventListener("click",async e=>{const start=e.target.closest("[data-tw-start]");if(start){e.preventDefault();e.stopImmediatePropagation();s={scene:0,selected:null,history:[]};history.pushState({},"",path);render();return}if(!active())return;const choice=e.target.closest("[data-tw-choice]");if(choice&&s.selected===null){e.preventDefault();e.stopImmediatePropagation();s.selected=Number(choice.dataset.twChoice);render("result");return}const el=e.target.closest("[data-tw-action]");if(!el)return;e.preventDefault();e.stopImmediatePropagation();const a=el.dataset.twAction;if(a==="continue"){s.history.push({...s});s.scene=adventure17.scenes[s.scene].next;s.selected=null;render()}else if(a==="back"&&s.selected!==null){s.selected=null;render("decision")}else if(a==="back"&&s.history.length){s=s.history.pop();render("result")}else if(a==="restart"){s={scene:0,selected:null,history:[]};render()}else if(a==="end"){history.pushState({},"","/");renderHome();setTimeout(tile,0)}else if(a==="share"){const d={title:adventure17.title,text:`I just tried “${adventure17.title}” on Tucson Adventures. What would you do?`,url:`${location.origin}${path}?fresh=1`};try{if(navigator.share)await navigator.share(d);else await navigator.clipboard.writeText(`${d.text} ${d.url}`)}catch(_){}}},true);new MutationObserver(()=>{if(!active())tile()}).observe(document.querySelector("#app"),{childList:true,subtree:true});window.addEventListener("popstate",()=>{if(active())render();else setTimeout(tile,0)});if(active())render();else tile()})();